 "content": "def transform(grid):
    """Continue an isolated same-color diagonal pair away from its blocking motif."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    additions = []

    # Every ray seed is a pair of equal cells on a unit diagonal. Extend only
    # toward the open side when the opposite continuation is occupied.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                before = (r - dr, c - dc)
                after = (r + 2 * dr, c + 2 * dc)
                before_in = 0 <= before[0] < h and 0 <= before[1] < w
                after_in = 0 <= after[0] < h and 0 <= after[1] < w
                before_blocked = before_in and grid[before[0]][before[1]] != bg
                after_blocked = after_in and grid[after[0]][after[1]] != bg
                if before_blocked and after_in and not after_blocked:
                    additions.append((r2 + dr, c2 + dc, dr, dc, color))
                elif after_blocked and before_in and not before_blocked:
                    additions.append((r - dr, c - dc, -dr, -dc, color))

    for r, c, dr, dc, color in additions:
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] != bg:
                break
            out[r][c] = color
            r += dr
            c += dc
    return out

